fn main() {
    let mut total = 0;
    for n in 1..=4 {
        total = total + n;
    }
    println!("1 + 2 + 3 + 4 = {total}");
}

fn main() {
    let mut countdown = 3;
    while countdown > 0 {
        println!("{countdown}...");
        countdown = countdown - 1;
    }
    println!("Lift off!");
}

